import { ref, onMounted } from "vue";
import { useRoute } from "vue-router";
import { ElButton, ElDialog, ElInput, ElMessage } from "element-plus"; // 引入 Element Plus 组件
import axios from "axios";
export default {
  __name: 'ProductPage',
  setup(__props, {
    expose: __expose
  }) {
    __expose();
    const paymentPassword = ref(""); // 创建响应式变量
    const route = useRoute();
    const product = ref({
      id: null,
      // 添加 id 属性
      name: "",
      price: 0,
      image: "",
      description: "",
      stock: 0
    });
    const optionsVisible = ref(false); // 控制购买选项的显示状态

    // 确定购买相关的状态
    const isDialogVisible = ref(false); // 确认购买对话框可见性
    const isPasswordDialogVisible = ref(false); // 输入密码对话框可见性

    // 获取商品详细信息
    onMounted(async () => {
      const productId = route.params.id;
      const response = await fetch(`http://localhost:5000/api/products/${productId}`);
      if (response.ok) {
        const productData = await response.json();
        product.value = productData.data;
        product.value.price = parseFloat(product.value.price) || 0;

        // 处理图片URL
        console.log("原始图片URL:", product.value.image);
        if (product.value.image) {
          // 如果图片路径以/assets/开头，直接使用
          if (product.value.image.startsWith("/assets/")) {
            product.value.image = `http://localhost:5000${product.value.image}`;
          }
        }
        console.log("处理后的图片URL:", product.value.image);
        console.log("获取的产品数据:", product.value);
      } else {
        console.error("获取商品详情失败，状态码:", response.status);
      }
    });

    // 加入购物车
    const addToCart = async () => {
      const quantity = 1;
      const token = localStorage.getItem("token");
      if (!token) {
        ElMessage.error("请先登录");
        return;
      }
      try {
        const response = await axios.post(`http://localhost:5000/api/cart?productId=${product.value.id}&quantity=${quantity}`, {}, {
          headers: {
            Authorization: `Bearer ${token}`
          }
        });
        if (response.data.success) {
          ElMessage.success(`${product.value.name} 已加入购物车！`);
        } else {
          ElMessage.error("加入购物车失败: " + response.data.message);
        }
      } catch (error) {
        console.error("加入购物车时发生错误:", error);
        ElMessage.error("加入购物车失败，请稍后重试。");
      }
    };

    // 显示购买选项
    const showPurchaseOptions = () => {
      optionsVisible.value = true; // 显示购买选项
    };

    // 打开确认购买对话框
    const askForPurchaseConfirmation = () => {
      isDialogVisible.value = true;
    };

    // 重置对话框状态
    const resetDialog = () => {
      isDialogVisible.value = false;
    };

    // 确认购买并打开输入密码对话框
    const confirmPurchase = () => {
      isDialogVisible.value = false;
      isPasswordDialogVisible.value = true;
    };

    // 重置密码输入对话框状态
    const resetPasswordDialog = () => {
      isPasswordDialogVisible.value = false;
      paymentPassword.value = ""; // 清空密码输入
    };

    // 提交购买
    const submitPurchase = async () => {
      const userId = localStorage.getItem("userId"); // 获取用户 ID
      localStorage.getItem("userId");
      const password = paymentPassword.value; // 获取用户输入的支付密码

      // 确认 product.value.id 和 stock 是否有效
      if (!product.value || !product.value.id) {
        alert("产品信息未正确加载，请确认产品存在！");
        return; // 结束函数执行
      }
      try {
        // 这里可以新增检查 purchaseAmount
        const quantity = 1; // 默认购买数量
        const paymentAmount = product.value.price; // 支付金额由产品价格决定

        // 先进行支付密码验证
        const response = await fetch("http://www.groupbuyingsystem.site/api/auth/check-payment-password", {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${localStorage.getItem("token")}`
          },
          body: JSON.stringify({
            inputPassword: password // 发送支付密码
          })
        });
        if (response.ok) {
          // 支付密码验证成功，进行购买操作生成订单
          const purchaseResponse = await fetch("http://www.groupbuyingsystem.site/api/purchase/products/orders",
          // 创建订单的 API
          {
            method: "POST",
            headers: {
              "Content-Type": "application/json",
              Authorization: `Bearer ${localStorage.getItem("token")}` // 进行身份验证
            },
            body: JSON.stringify({
              userId: userId,
              // 用户 ID
              productId: product.value.id,
              // 产品 ID
              quantity: quantity,
              // 购买数量
              paymentAmount: paymentAmount // 支付金额
            })
          });
          if (purchaseResponse.ok) {
            // 支付密码验证成功，进行购买操作
            const purchaseResponse1 = await fetch("http://www.groupbuyingsystem.site/api/purchase/products",
            // 创建订单的 API
            {
              method: "POST",
              headers: {
                "Content-Type": "application/json",
                Authorization: `Bearer ${localStorage.getItem("token")}` // 进行身份验证
              },
              body: JSON.stringify({
                userId: userId,
                // 用户 ID
                productId: product.value.id,
                // 产品 ID
                quantity: quantity,
                // 购买数量
                paymentAmount: paymentAmount // 支付金额
              })
            });
            if (purchaseResponse1.ok) {
              alert(`${product.value.name} 购买成功！`);
            } else {
              const errorData = await purchaseResponse.json();
              alert("购买失败: " + errorData.message);
            }
          } else {
            const errorData = await response.json();
            alert("支付密码验证失败: " + errorData.message);
          }
        }
      } catch (error) {
        console.error("购买时发生错误:", error);
        alert("购买失败，请稍后重试。");
      }
    };
    // 拼团购买
    const purchaseAsGroup = () => {
      alert("选择拼团购买功能！");
    };

    // 单独购买

    const __returned__ = {
      paymentPassword,
      route,
      product,
      optionsVisible,
      isDialogVisible,
      isPasswordDialogVisible,
      addToCart,
      showPurchaseOptions,
      askForPurchaseConfirmation,
      resetDialog,
      confirmPurchase,
      resetPasswordDialog,
      submitPurchase,
      purchaseAsGroup,
      ref,
      onMounted,
      get useRoute() {
        return useRoute;
      },
      get ElButton() {
        return ElButton;
      },
      get ElDialog() {
        return ElDialog;
      },
      get ElInput() {
        return ElInput;
      },
      get ElMessage() {
        return ElMessage;
      },
      get axios() {
        return axios;
      }
    };
    Object.defineProperty(__returned__, '__isScriptSetup', {
      enumerable: false,
      value: true
    });
    return __returned__;
  }
};
